    char currentRumour[0x12d];               // +0x4e419
    char rumourState[0x100];                 // +0x4e546
    char pad_4e646[2];
    std::vector<TRumour> rumours;             // +0x4e648
    char field_4e658[0x1c];
    char pad_4e674[8];
